export type LinkedToken = { text: string; href?: string };

export function jsxString(value: string): string {
  return `{${JSON.stringify(value)}}`;
}

export function responseField(
  name: string,
  type: string,
  optional: boolean,
  body?: string,
  typeHref?: string,
  id?: string
): string {
  const idAttr = id ? ` id=${jsxString(id)}` : '';
  const typeAttr = type ? ` type=${jsxString(truncate(type, 80))}` : '';
  const typeHrefAttr = typeHref ? ` typeHref=${jsxString(typeHref)}` : '';
  const requiredAttr = optional ? '' : ' required';
  return `<ResponseField name=${jsxString(name)}${idAttr}${typeAttr}${typeHrefAttr}${requiredAttr}>\n${indent(body || '')}\n</ResponseField>`;
}

export function escapeInline(text: string): string {
  return collapseWhitespace(text).replace(/[\\`*_{}[\]<>]/g, '\\$&');
}

// Code spans and link text are inline; a blank line inside them would end the
// paragraph and let the remainder parse as MDX. Line endings (\n, \r, and
// \r\n, which CommonMark treats alike) become one space along with the
// indentation that follows them; other whitespace is kept, so a string literal
// such as "a  b" keeps its spacing. The pattern cannot backtrack, so a long
// run of spaces costs linear time.
export function collapseWhitespace(text: string): string {
  return text.replace(/[\r\n]+[ \t]*/g, ' ');
}

const SAFE_SCHEMES = /^(?:https?|mailto):/i;

// Keeps http(s), mailto, fragments and relative paths; drops javascript:,
// data:, and every other scheme so artifact text cannot produce an active link.
// Browsers drop C0 controls, spaces, and DEL while parsing a URL and read a
// backslash as a slash, so the check runs on the URL as a browser would see it.
// The returned URL keeps its interior spaces (a file can be named "Getting
// Started.md") and loses only what a browser drops: surrounding controls and
// spaces, and tabs or newlines anywhere.
//
// A character reference before the first `/`, `?`, or `#` (after any leading
// slashes, so `/&sol;evil.com` cannot become `//evil.com`) is refused: Markdown
// leaves `&colon;` and `&#58;` in reference definitions for MDX to decode, so
// `javascript&colon;x` would become `javascript:x` after this check ran.
export function safeHref(url: string): string | undefined {
  const cleaned = url.replace(/[\u0000-\u0020\u007f]/g, '');
  const kept = trimControls(url).replace(/[\t\n\r]/g, '');
  if (cleaned === '' || cleaned.startsWith('#')) return kept;
  if (/&[#a-z]/i.test(cleaned.replace(/^[\\/]+/, '').split(/[/?#]/, 1)[0] ?? '')) return undefined;
  if (
    /^[a-z][a-z0-9+.-]*:/i.test(cleaned) ||
    /^[\\/][\\/]/.test(cleaned) ||
    cleaned.startsWith('\\')
  ) {
    return SAFE_SCHEMES.test(cleaned) ? kept : undefined;
  }
  return kept;
}

// Trims C0 controls and spaces from both ends with two index scans; a regex
// with a `$` alternative retries from every position of a long interior run.
function trimControls(url: string): string {
  let start = 0;
  let end = url.length;
  while (start < end && url.charCodeAt(start) <= 0x20) start += 1;
  while (end > start && url.charCodeAt(end - 1) <= 0x20) end -= 1;
  return url.slice(start, end);
}

export function encodeHref(text: string): string {
  return text
    .split('/')
    .map((segment) =>
      encodeURIComponent(segment).replace(
        /[()!'*]/g,
        (char) => `%${char.charCodeAt(0).toString(16).toUpperCase()}`
      )
    )
    .join('/');
}

export function linkedCode(tokens: LinkedToken[]): string | undefined {
  if (!tokens.some((token) => token.href)) return undefined;
  const merged: LinkedToken[] = [];
  for (const token of tokens) {
    const last = merged.at(-1);
    if (last && !last.href && !token.href) last.text += token.text;
    else merged.push({ ...token });
  }
  const children = merged
    .map((token) =>
      token.href
        ? `[${escapeInline(token.text)}](${token.href})`
        : jsxString(collapseWhitespace(token.text))
    )
    .join('');
  return `<code>${children}</code>`;
}

export function indent(text: string): string {
  return text
    .split('\n')
    .map((line) => (line ? `  ${line}` : line))
    .join('\n');
}

export function truncate(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, max - 1)}…` : text;
}

export function inlineCode(text: string): string {
  const code = collapseWhitespace(text).trim();
  if (!code) return text;
  const longestRun = Math.max(0, ...(code.match(/`+/g) ?? []).map((run) => run.length));
  const fence = '`'.repeat(longestRun + 1);
  const pad = code.startsWith('`') || code.endsWith('`') ? ' ' : '';
  return `${fence}${pad}${code}${pad}${fence}`;
}
